"use client"

import { useState, useRef, useEffect } from "react"
import { useRouter } from "next/navigation"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Upload, X, Smartphone, Check, Share2, Copy, QrCode } from "lucide-react"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import Image from "next/image"

const scrollSizes = [
  { width: 690, label: "네이버", description: "가로 690px, 세로 무제한" },
  { width: 690, label: "봄툰", description: "가로 690px, 세로 무제한" },
  { width: 720, label: "레진", description: "가로 720px, 세로 무제한" },
]

export default function MobileScrollPage() {
  const router = useRouter()
  const [networkIp, setNetworkIp] = useState<string>("localhost")
  const [isPublicUrl, setIsPublicUrl] = useState<boolean>(false)
  const [publicIp, setPublicIp] = useState<string>("")
  const [images, setImages] = useState<(string | null)[]>([null, null, null])
  const [completed, setCompleted] = useState<boolean[]>([false, false, false])
  const [shareUrl, setShareUrl] = useState<string>("")
  const [isShareModalOpen, setIsShareModalOpen] = useState(false)
  const fileInputRefs = [
    useRef<HTMLInputElement>(null),
    useRef<HTMLInputElement>(null),
    useRef<HTMLInputElement>(null),
  ]

  useEffect(() => {
    fetch('/api/network-ip')
      .then(res => res.json())
      .then(data => {
        if (data.ip) {
          setNetworkIp(data.ip)
          setIsPublicUrl(data.isPublic || false)
          if (data.publicIp) setPublicIp(data.publicIp)
        }
      })
      .catch(console.error)
  }, [])

  const handleImageUpload = (
    index: number,
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    const file = e.target.files?.[0]
    if (file) {
      const reader = new FileReader()
      reader.onloadend = () => {
        const newImages = [...images]
        newImages[index] = reader.result as string
        setImages(newImages)
      }
      reader.readAsDataURL(file)
    }
  }

  const handleRemoveImage = (index: number) => {
    const newImages = [...images]
    newImages[index] = null
    setImages(newImages)
    const newCompleted = [...completed]
    newCompleted[index] = false
    setCompleted(newCompleted)
  }

  const handleComplete = (index: number) => {
    const newCompleted = [...completed]
    newCompleted[index] = true
    setCompleted(newCompleted)
  }

  const handleViewPage = async (index: number) => {
    const size = scrollSizes[index]
    const imageData = images[index]
    if (imageData) {
      // Create a unique ID for the image
      const imageId = Date.now().toString() + Math.random().toString(36).substring(2)
      
      // Store image temporarily on server so mobile devices can access it via network IP
      try {
        const res = await fetch('/api/image', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: imageId, data: imageData })
        })

        if (!res.ok) {
          throw new Error('Failed to upload');
        }

        // Also keep sessionStorage as fallback for PC
        sessionStorage.setItem("scrollViewerImage", imageData)
        
        const params = new URLSearchParams({
          width: size.width.toString(),
          label: size.label,
          id: imageId
        })
        window.open(`/mobile-scroll/viewer?${params.toString()}`, "_blank")
      } catch (error) {
        console.error('Failed to upload image to server for sharing', error)
        // Fallback to PC only view if server storage fails
        sessionStorage.setItem("scrollViewerImage", imageData)
        const params = new URLSearchParams({
          width: size.width.toString(),
          label: size.label,
        })
        window.open(`/mobile-scroll/viewer?${params.toString()}`, "_blank")
      }
    }
  }

  const handleCopyMobileLink = async (index: number) => {
    const size = scrollSizes[index]
    const imageData = images[index]
    if (imageData) {
      const imageId = Date.now().toString() + Math.random().toString(36).substring(2)
      
      try {
        const res = await fetch('/api/image', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: imageId, data: imageData })
        })

        if (!res.ok) {
          throw new Error('Failed to upload');
        }

        const params = new URLSearchParams({
          width: size.width.toString(),
          label: size.label,
          id: imageId
        })
        
        let mobileUrl = "";
        if (isPublicUrl) {
          mobileUrl = `${networkIp}/mobile-scroll/viewer?${params.toString()}`
        } else {
          const port = window.location.port ? `:${window.location.port}` : ''
          mobileUrl = `http://${networkIp}${port}/mobile-scroll/viewer?${params.toString()}`
        }
        
        setShareUrl(mobileUrl)
        setIsShareModalOpen(true)
      } catch (error) {
        console.error('Failed to generate sharing link', error)
        alert("링크를 생성하는데 실패했습니다.")
      }
    }
  }

  const copyToClipboard = async () => {
    try {
      await navigator.clipboard.writeText(shareUrl)
      alert("모바일용 링크가 복사되었습니다!\n카카오톡 등으로 스마트폰에 보내거나 QR 코드를 스캔하세요.")
    } catch {
      alert("복사에 실패했습니다.")
    }
  }

  return (
    <div className="mx-auto max-w-4xl">
      <div className="mb-8">
        <h1 className="flex items-center gap-3 text-3xl font-bold tracking-tight text-foreground">
          <Smartphone className="h-8 w-8 text-primary" />
          작품 스크롤 확인 (모바일용)
        </h1>
        <p className="mt-2 text-muted-foreground">
          모바일 환경에서 스크롤 형태의 작품이 어떻게 보이는지 확인할 수
          있습니다.
        </p>
      </div>

      <div className="grid gap-8">
        {scrollSizes.map((size, index) => (
          <Card key={index} className="border-border bg-card">
            <CardHeader>
              <CardTitle className="flex items-center justify-between text-card-foreground">
                <div>
                  <span className="text-primary">{size.label}</span>
                  <span className="ml-2 text-sm font-normal text-muted-foreground">
                    {size.description}
                  </span>
                </div>
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div
                className="relative mx-auto flex min-h-64 items-center justify-center overflow-auto rounded-lg border-2 border-dashed border-border bg-secondary"
                style={{
                  width: "100%",
                  maxWidth: Math.min(size.width, 400),
                  maxHeight: 500,
                }}
              >
                {images[index] ? (
                  <div className="relative w-full">
                    <Image
                      src={images[index]!}
                      alt={`Scroll image ${index + 1}`}
                      width={size.width}
                      height={0}
                      className="h-auto w-full mb-12"
                      unoptimized
                    />
                    <div className="absolute right-2 bottom-2 flex flex-wrap gap-2">
                      <Button
                        variant="secondary"
                        size="sm"
                        className="gap-1 shadow-md bg-white text-black hover:bg-zinc-100"
                        onClick={() => handleCopyMobileLink(index)}
                      >
                        <QrCode className="h-4 w-4" />
                        폰으로 보기
                      </Button>
                      <Button
                        variant="default"
                        size="sm"
                        className="gap-1 shadow-md"
                        onClick={() => handleViewPage(index)}
                      >
                        <Check className="h-4 w-4" />
                        확인
                      </Button>
                      <Button
                        variant="destructive"
                        size="icon"
                        className="h-8 w-8 shadow-md"
                        onClick={() => handleRemoveImage(index)}
                      >
                        <X className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                ) : (
                  <div className="flex flex-col items-center gap-3 py-8 text-muted-foreground">
                    <input
                      ref={fileInputRefs[index]}
                      type="file"
                      accept="image/*"
                      onChange={(e) => handleImageUpload(index, e)}
                      className="hidden"
                    />
                    <Button
                      variant="outline"
                      onClick={() => fileInputRefs[index].current?.click()}
                      className="gap-2"
                    >
                      <Upload className="h-4 w-4" />
                      이미지 업로드
                    </Button>
                    <p className="text-sm">
                      가로 {size.width}px, 세로 무제한
                    </p>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      <Dialog open={isShareModalOpen} onOpenChange={setIsShareModalOpen}>
        <DialogContent className="sm:max-w-md flex flex-col items-center justify-center p-8">
          <DialogHeader className="w-full text-center">
            <DialogTitle className="text-xl">모바일로 보기</DialogTitle>
            <DialogDescription>
              스마트폰 카메라로 QR 코드를 스캔하세요.
            </DialogDescription>
          </DialogHeader>

          <div className="my-6 rounded-xl bg-white p-4 shadow-sm border border-slate-100 flex justify-center w-full">
            {shareUrl ? (
              <img
                src={`https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(shareUrl)}`}
                alt="QR Code"
                width={200}
                height={200}
                className="rounded-lg object-contain w-[200px] h-[200px]"
              />
            ) : (
              <div className="w-[200px] h-[200px] bg-slate-100 rounded-lg animate-pulse" />
            )}
          </div>

          <p className="text-sm text-center text-muted-foreground w-full break-all mb-4 px-4 py-2 bg-secondary rounded-md">
            {shareUrl}
          </p>

          <div className="flex w-full gap-3 sm:flex-row flex-col justify-center">
            <Button onClick={copyToClipboard} variant="outline" className="gap-2">
              <Copy className="h-4 w-4" />
              링크 복사
            </Button>
            <Button onClick={() => setIsShareModalOpen(false)}>
              닫기
            </Button>
          </div>

          {publicIp && (
            <div className="mt-6 w-full rounded-lg bg-orange-50 p-4 text-sm text-orange-900 border border-orange-200">
              <span className="block font-bold mb-1 text-orange-950">⚠️ 초기 보안 화면 통과 방법</span>
              스마트폰 화면에 IP 입력칸이 나오면 아래의 IP(비밀번호)를 입력하고 <strong className="bg-orange-100 px-1 rounded">Submit</strong> 을 누르세요.
              <div className="mt-2 text-center text-lg font-mono font-bold tracking-widest text-orange-600 bg-white py-2 rounded border border-orange-100">
                {publicIp}
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  )
}
